import {el,field,button,busy,notify} from './utils.js';
import {api} from './service.js';
export function executionPolicyForm(data,refresh){const limits=data.executionPolicy||{accountPerDay:10,channelPerDay:10};const account=el('input',{class:'field-control',type:'number','data-retain-input':'true',min:1,max:500,step:1});account.value=String(limits.accountPerDay);const channel=el('input',{class:'field-control',type:'number','data-retain-input':'true',min:1,max:500,step:1});channel.value=String(limits.channelPerDay);const panel=el('section',{class:'info-card'},el('h3',{text:'Daily execution budgets'}),field('Actions per account per day',account),field('Actions per channel per day',channel),el('p',{class:'flow-note',text:'These budgets apply to newly prepared plans. Existing approvals keep their reviewed policy. Account and platform restrictions remain enforced.'}));if(data.roles?.includes('admin')){const save=button('Save daily budgets',()=>busy(save,async()=>{if(!account.validity.valid||!channel.validity.valid){account.reportValidity();channel.reportValidity();return;}await api('policy-settings-save',{input:{accountPerDay:Number(account.value),channelPerDay:Number(channel.value)}});await refresh();notify('Daily budgets updated for new plan reviews.');}),'primary');panel.append(save);}else{account.disabled=true;channel.disabled=true;}return panel;}
